style.css:
@-moz-document domain("youtube.com") {
html, body {
    background: url("https://i.pinimg.com/1200x/36/09/7d/36097d10c54d49a96a355ce098c7180a.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Make main containers transparent so wallpaper shows through */
  #content, #page-manager, #masthead-container, #guide-content {
    background: transparent !important;
  }
}
